def score_bucket_counts(scores):
    from collections import Counter

    def label(score):
        if score >= 100:
            return '100+'
        base = (score // 10) * 10
        return f'{base}-{base + 9}'

    return dict(Counter(label(s) for s in scores))

def count_days_in_leap_years(year1, year2):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    years = range(year1, year2 + 1)
    leap_count = sum(1 for y in years if is_leap(y))
    total_years = year2 - year1 + 1
    return total_years * 365 + leap_count

def is_balanced_ignoring_escapes(s):
    def helper(i, depth):
        if i >= len(s):
            return depth == 0
        if s[i] == '\\' and i + 1 < len(s) and s[i + 1] in '()':
            return helper(i + 2, depth)
        if s[i] == '(':
            return helper(i + 1, depth + 1)
        if s[i] == ')':
            if depth == 0:
                return False
            return helper(i + 1, depth - 1)
        return helper(i + 1, depth)
    return helper(0, 0)

