def rank_normalize_scores(scores):
    n = len(scores)
    if n <= 1:
        return [0.0] * n
    result = []
    for v in scores:
        less_count = sum(1 for x in scores if x < v)
        result.append(round(less_count / (n - 1), 4))
    return result

