def count_char_categories(s):
    from collections import Counter

    def category(ch):
        if ch.isdigit():
            return 'digits'
        if ch.isalpha():
            return 'letters'
        if ch.isspace():
            return 'spaces'
        return 'other'

    counts = Counter(category(ch) for ch in s)
    return {k: counts.get(k, 0) for k in ('digits', 'letters', 'spaces', 'other')}

